// src/server/persistence/migrations/turn-association-columns.ts
var TURN_ASSOCIATION_TABLES = [
  "messages",
  "activities",
  "agent_reasonings",
  "agent_plans",
  "thread_usage",
  "checkpoints"
];
var TURN_ASSOCIATION_COLUMNS = ["turn_id"];
function ensureTurnAssociationColumns(database) {
  for (const table of TURN_ASSOCIATION_TABLES) {
    const tableSql2 = quotedSqlIdentifier(table, TURN_ASSOCIATION_TABLES);
    const columnSql = quotedSqlIdentifier(
      "turn_id",
      TURN_ASSOCIATION_COLUMNS
    );
    const columns2 = database.prepare(`PRAGMA table_info(${tableSql2})`).all();
    if (columns2.some(({ name }) => name === "turn_id")) continue;
    database.exec(
      `ALTER TABLE ${tableSql2} ADD COLUMN ${columnSql} TEXT REFERENCES agent_turns(id) ON DELETE SET NULL`
    );
  }
}

