var CLEANUP_ADMISSION_TIMEOUT_MS = 1e3;
function attachmentCleanupAuthority(store, turns) {
  return async (ids) => {
    const acquired = await Promise.allSettled(store.attachmentConversationIds(ids).map((conversationId) => turns.acquireTurnAdmission(conversationId, CLEANUP_ADMISSION_TIMEOUT_MS)));
    const leases = acquired.flatMap((result2) => result2.status === "fulfilled" && result2.value ? [result2.value] : []);
    const leased = new Set(leases.map(({ conversationId }) => conversationId));
    return {
      order: () => store.evictableAttachmentIds(leased),
      release: () => {
        for (const lease of leases) lease.release();
      }
    };
  };
}

